-- Hala Talab Driver Stage 16: free customer delivery + separate driver dues
update public.stores set delivery_fee=0 where coalesce(delivery_fee,0)<>0;
create or replace function public.hala_force_free_delivery() returns trigger language plpgsql set search_path=public as $$ declare f numeric:=greatest(coalesce(new.delivery_fee,0),0); begin if f<>0 then new.total:=greatest(coalesce(new.total,0)-f,0); end if; new.delivery_fee:=0; return new; end $$;
drop trigger if exists trg_hala_force_free_delivery on public.orders; create trigger trg_hala_force_free_delivery before insert or update of delivery_fee on public.orders for each row execute function public.hala_force_free_delivery();
update public.orders set total=greatest(coalesce(total,0)-greatest(coalesce(delivery_fee,0),0),0),delivery_fee=0 where status<>'delivered' and coalesce(delivery_fee,0)<>0;
create table if not exists public.driver_compensation_profiles(driver_id uuid primary key,pay_type text not null default 'custom' check(pay_type in('fixed','daily','weekly','monthly','custom')),base_amount numeric(12,2) not null default 0 check(base_amount>=0),active boolean not null default true,note text,updated_at timestamptz not null default now());
create table if not exists public.driver_dues(id bigint generated by default as identity primary key,driver_id uuid not null,amount numeric(12,2) not null check(amount>=0),kind text not null default 'base' check(kind in('base','daily','weekly','monthly','bonus','adjustment')),period_label text,due_date date,note text,created_at timestamptz not null default now());
create table if not exists public.driver_payments(id bigint generated by default as identity primary key,driver_id uuid not null,amount numeric(12,2) not null check(amount>0),period_label text,note text,paid_at timestamptz not null default now(),created_at timestamptz not null default now());
alter table public.driver_compensation_profiles enable row level security; alter table public.driver_dues enable row level security; alter table public.driver_payments enable row level security;
drop policy if exists driver_read_own_compensation on public.driver_compensation_profiles; create policy driver_read_own_compensation on public.driver_compensation_profiles for select to authenticated using(driver_id=auth.uid());
drop policy if exists driver_read_own_dues on public.driver_dues; create policy driver_read_own_dues on public.driver_dues for select to authenticated using(driver_id=auth.uid());
drop policy if exists driver_read_own_payments on public.driver_payments; create policy driver_read_own_payments on public.driver_payments for select to authenticated using(driver_id=auth.uid());
create or replace function public.get_driver_dues_summary() returns jsonb language sql security definer set search_path=public as $$ with p as(select pay_type,base_amount from driver_compensation_profiles where driver_id=auth.uid() and active limit 1),d as(select coalesce(sum(amount)filter(where kind<>'bonus'),0)::numeric base_due,coalesce(sum(amount)filter(where kind='bonus'),0)::numeric bonus_due from driver_dues where driver_id=auth.uid()),x as(select coalesce(sum(amount),0)::numeric paid_amount from driver_payments where driver_id=auth.uid()),w as(select count(*)filter(where status='delivered')::int delivered_orders,count(distinct coalesce(delivered_at,updated_at,created_at)::date)filter(where status='delivered')::int work_days,count(*)filter(where status='delivered' and coalesce(delivered_at,updated_at,created_at)>=date_trunc('day',now()))::int today_orders from orders where driver_id=auth.uid()),t as(select coalesce(jsonb_agg(jsonb_build_object('id',id,'amount',amount,'period_label',period_label,'note',note,'paid_at',paid_at)order by paid_at desc),'[]'::jsonb) rows from(select * from driver_payments where driver_id=auth.uid() order by paid_at desc limit 30)q) select jsonb_build_object('pay_type',coalesce((select pay_type from p),'custom'),'pay_type_label',case coalesce((select pay_type from p),'custom') when 'daily' then 'يومي' when 'weekly' then 'أسبوعي' when 'monthly' then 'شهري' when 'fixed' then 'ثابت' else 'حسب اتفاق الإدارة' end,'base_due',d.base_due,'bonus_due',d.bonus_due,'paid_amount',x.paid_amount,'outstanding_due',greatest(d.base_due+d.bonus_due-x.paid_amount,0),'delivered_orders',w.delivered_orders,'work_days',w.work_days,'today_orders',w.today_orders,'payments',t.rows)from d,x,w,t; $$;
revoke all on function public.get_driver_dues_summary() from public; grant execute on function public.get_driver_dues_summary() to authenticated; notify pgrst,'reload schema';
